const turns = $json.body.turns || [];
const repTurns = turns.filter(t => t.speaker === 'rep');

const objectionWords = /price|expensive|competitor|think about it|not sure|budget|later|talk to my|need to check/i;

const opening = repTurns.slice(0, 3);
const closing = repTurns.slice(-3);
const objectionTurns = repTurns.filter(t => objectionWords.test(t.text));

const seen = new Set();
const excerpt = [...opening, ...objectionTurns, ...closing]
  .filter(t => {
    const key = t.ts + t.text.slice(0, 20);
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  })
  .sort((a, b) => a.ts - b.ts);

const repText = excerpt.map(t => `[${t.ts}s] ${t.text}`).join('\n');
const fullRepText = repTurns.map(t => `[${t.ts}s] ${t.text}`).join('\n');

return [{
  json: {
    call_id: $json.body.call_id,
    rep_name: $json.body.rep_name,
    customer_name: $json.body.customer_name,
    company: $json.body.company,
    call_date: $json.body.call_date,
    duration_minutes: $json.body.duration_minutes,
    rep_excerpt: repText,
    rep_full_text: fullRepText
  }
}];

