const raw = $json.output?.[0]?.content?.[0]?.text
  ?? $json.message?.content
  ?? $json.content
  ?? "";

let parsed;
try {
  const cleaned = raw
    .replace(/```json|```/g, "")
    .replace(/,(\s*[}\]])/g, "$1")  // strip trailing commas before } or ]
    .trim();
  parsed = typeof raw === "string" ? JSON.parse(cleaned) : raw;
} catch (e) {
  return [{ json: { ...$('Extract Rep Turns').item.json, valid: false, fail_reason: "unparseable" } }];
}

const categories = ['discovery', 'objection_handling', 'value_framing', 'next_steps', 'tone'];
const fullText = $('Extract Rep Turns').item.json.rep_full_text.toLowerCase();
const failed = [];

for (const cat of categories) {
  const entry = parsed[cat];
  if (!entry || typeof entry.score !== 'number' || entry.score < 1 || entry.score > 5) {
    failed.push(`${cat}:bad_score`);
    continue;
  }
  if (entry.evidence_quote) {
    const quoteClean = entry.evidence_quote.toLowerCase().replace(/^\[\d+s\]\s*/, '').trim();
    if (quoteClean.length > 8 && !fullText.includes(quoteClean)) {
      failed.push(`${cat}:quote_not_found`);
    }
  }
}

const overall = categories.reduce((sum, c) => sum + (parsed[c]?.score || 0), 0) / categories.length;

return [{ json: {
  ...$('Extract Rep Turns').item.json,
  scores: parsed,
  overall_score: Math.round(overall * 10) / 10,
  valid: failed.length === 0,
  fail_reason: failed.join(",")
}}];

