function groupByRep(rows) {
  const byRep = {};
  for (const r of rows) {
    if (!byRep[r.rep_name]) byRep[r.rep_name] = [];
    byRep[r.rep_name].push(r);
  }
  return byRep;
}

const thisWeek = groupByRep($("Pull This Week's Scores").all().map(i => i.json));
const lastWeek = groupByRep($("Pull Prior Week's Scores").all().map(i => i.json));

const categories = ['discovery', 'objection_handling', 'value_framing', 'next_steps', 'tone'];
const results = [];

for (const rep of Object.keys(thisWeek)) {
  const calls = thisWeek[rep];
  const avgThis = calls.reduce((s, c) => s + Number(c.overall_score), 0) / calls.length;
  const priorCalls = lastWeek[rep] || [];
  const avgLast = priorCalls.length
    ? priorCalls.reduce((s, c) => s + Number(c.overall_score), 0) / priorCalls.length
    : null;

  let weakest = null;
  for (const c of calls) {
    for (const cat of categories) {
      const entry = c.scores?.[cat];
      if (entry?.evidence_quote && (!weakest || entry.score < weakest.score)) {
        weakest = { category: cat, ...entry };
      }
    }
  }

  results.push({
    rep_name: rep,
    calls_this_week: calls.length,
    avg_this_week: Math.round(avgThis * 10) / 10,
    avg_last_week: avgLast ? Math.round(avgLast * 10) / 10 : null,
    trend: avgLast ? Math.round((avgThis - avgLast) * 10) / 10 : null,
    weakest_moment: weakest
  });
}

return results.map(r => ({ json: r }));

