const raw = $json.output?.[0]?.content?.[0]?.text
  ?? $json.message?.content
  ?? $json.content
  ?? "";

let parsed;
try {
  const cleaned = raw
    .replace(/```json|```/g, "")
    .replace(/,(\s*[}\]])/g, "$1")
    .trim();
  parsed = typeof raw === "string" ? JSON.parse(cleaned) : raw;
} catch (e) {
  return [{ json: { ...$('Loop Over Reps').item.json, valid: false, fail_reason: "unparseable" } }];
}

const note = (parsed.coaching_note || "").trim();
const wordCount = note.split(/\s+/).length;

const checks = {
  hasNote: note.length > 20,
  wordCountOk: wordCount <= 120,
  noAiTells: !/as an AI|I hope this|circling back/i.test(note)
};

const failed = Object.entries(checks).filter(([, v]) => !v).map(([k]) => k);

return [{ json: {
  ...$('Loop Over Reps').item.json,
  coaching_note: note,
  valid: failed.length === 0,
  fail_reason: failed.join(",")
}}];

const r = $json;
const trendArrow = r.trend > 0 ? '↑' : r.trend < 0 ? '↓' : '→';
return [{ json: {
  message: `${r.rep_name} — ${r.avg_this_week}/5 (${trendArrow} ${r.trend ?? 'n/a'})\n${r.coaching_note}`
}}];
